package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.media3.datasource.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import java.util.*;import java.security.*;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=android.app.Application.class)
public class LibraryUi163Test {
 Context c;
 public static class FakeMain extends MainActivity {protected ScApi createApi(){return new ScApi(this){public Page likes(String user,String next)throws Exception{ScApi.Page p=new ScApi.Page();p.tracks.add(song("1","Первый трек"));p.tracks.add(song("2","Второй трек"));return p;}public Page playlists(String user,boolean liked,String next)throws Exception{Page p=new Page();for(String id:liked?new String[]{"b","c"}:new String[]{"a","b"})p.playlists.add(new JSONObject().put("id",id).put("title",id));return p;}public ArrayList<Library.Track> playlistTracks(String id)throws Exception{return new ArrayList<>(Arrays.asList(song(id,"Песня "+id)));}};}}
 static Library.Track song(String id,String title)throws Exception{Library.Track t=new Library.Track("sc:"+id,title,"Артист",180000,true);t.remote=new JSONObject().put("id",id).put("full_duration",180000);return t;}
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();Provider p=new Provider("VolnaSyntheticKeyStore",1.0,"test only"){};p.put("KeyStore.AndroidKeyStore",WarmWriterTest.MemoryStore.class.getName());Security.insertProviderAt(p,1);Session.put(c,"OAuth SYNTHETIC_UI163_TOKEN_12345","SYNTHETIC_UI163_CLIENT_12345");android.net.ConnectivityManager cm=c.getSystemService(android.net.ConnectivityManager.class);Shadows.shadowOf(cm).setActiveNetworkInfo(org.robolectric.shadows.ShadowNetworkInfo.newInstance(android.net.NetworkInfo.DetailedState.CONNECTED,android.net.ConnectivityManager.TYPE_WIFI,0,true,true));android.net.NetworkCapabilities caps=new android.net.NetworkCapabilities();Shadows.shadowOf(caps).addTransportType(android.net.NetworkCapabilities.TRANSPORT_WIFI);Shadows.shadowOf(caps).addCapability(android.net.NetworkCapabilities.NET_CAPABILITY_INTERNET);Shadows.shadowOf(cm).setNetworkCapabilities(cm.getActiveNetwork(),caps);}
 @After public void cleanup(){PlaybackService.instance=null;Security.removeProvider("VolnaSyntheticKeyStore");}
 Object field(Object obj,String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(obj);}
 List<View> all(View v){ArrayList<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)out.addAll(all(g.getChildAt(i)));}return out;}
 EditText search(Activity a){for(View v:all(a.getWindow().getDecorView()))if(v instanceof EditText&&"Поиск в медиатеке".contentEquals(v.getContentDescription()))return (EditText)v;throw new AssertionError("Missing library search");}
 void waitFor(MainActivity a)throws Exception{long until=System.currentTimeMillis()+6000;do{Shadows.shadowOf(Looper.getMainLooper()).idle();if(!(Boolean)field(a,"busy"))return;Thread.sleep(15);}while(System.currentTimeMillis()<until);fail("Request not finished");}
 ActivityController<FakeMain> screen(String filter,String id)throws Exception{Bundle b=new Bundle();b.putString("process",SoundFlowApplication.PROCESS);b.putString("page","library");b.putString("filter",filter);b.putString("playlistId",id);b.putString("playlist","Test");ActivityController<FakeMain> ctrl=Robolectric.buildActivity(FakeMain.class).create(b);waitFor(ctrl.get());return ctrl;}
 @Test public void likedSearchFiltersAndRestoresWithoutApiReload()throws Exception{ActivityController<FakeMain> ctrl=screen("likes","");assertEquals(2,((List<?>)field(ctrl.get(),"visible")).size());search(ctrl.get()).setText("второй");assertEquals(1,((List<?>)field(ctrl.get(),"visible")).size());search(ctrl.get()).setText("");assertEquals(2,((List<?>)field(ctrl.get(),"visible")).size());ctrl.destroy();}
 @Test public void playlistHasWorkingLocalSearch()throws Exception{ActivityController<FakeMain> ctrl=screen("playlists","a");search(ctrl.get()).setText("absent");assertEquals(0,((List<?>)field(ctrl.get(),"visible")).size());search(ctrl.get()).setText("песня");assertEquals(1,((List<?>)field(ctrl.get(),"visible")).size());ctrl.destroy();}
 @Test public void collectionSearchScansOwnAndLikedPlaylists()throws Exception{ActivityController<FakeMain> ctrl=screen("playlists","");search(ctrl.get()).setText("песня");Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(500));waitFor(ctrl.get());assertFalse((Boolean)field(ctrl.get(),"showPlaylists"));assertEquals(3,((List<?>)field(ctrl.get(),"visible")).size());search(ctrl.get()).setText("");Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(500));waitFor(ctrl.get());assertTrue((Boolean)field(ctrl.get(),"showPlaylists"));assertEquals(2,((List<?>)field(ctrl.get(),"cloudPlaylists")).size());ctrl.destroy();}
 Library.Track copy()throws Exception{Library.Track t=song("1","Сохранённая песня");ScApi fake=new ScApi(c){public Library.Track freshTrack(Library.Track old){return t;}public Stream playable(Library.Track old,boolean offline){return new Stream("https://cf-media.sndcdn.com/ui163.mp3",false,"",false,180000);}};return new OfflineStore(c){protected ScApi api(){return fake;}protected DataSource.Factory networkSource(){return ()->new ByteArrayDataSource(new byte[1024]);}protected long measuredCache(DataSource.Factory f,String u){return 180000;}}.save(t,new OfflineStore.Progress(){public boolean cancelled(){return false;}public void update(int p){}});}
 @Test public void offlineSearchDoesNotNeedCatalog()throws Exception{copy();ActivityController<FakeMain> ctrl=screen("offline","");search(ctrl.get()).setText("сохраненная");assertEquals(1,((List<?>)field(ctrl.get(),"visible")).size());search(ctrl.get()).setText("не найдется");assertEquals(0,((List<?>)field(ctrl.get(),"visible")).size());ctrl.destroy();}
 @Test public void cloudTrackMenuOffersDeleteWhenCopyExists()throws Exception{copy();ActivityController<FakeMain> ctrl=screen("likes","");Method menu=MainActivity.class.getDeclaredMethod("trackMenu",Library.Track.class);menu.setAccessible(true);menu.invoke(ctrl.get(),song("1","Первый трек"));AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals("Удалить из офлайна",d.getListView().getAdapter().getItem(2));d.dismiss();ctrl.destroy();}
 @Test public void deletingCloudCopyPreservesLikeAndAddsExclusion()throws Exception{Library.Track saved=copy();ActivityController<FakeMain> ctrl=screen("likes","");Method menu=MainActivity.class.getDeclaredMethod("trackMenu",Library.Track.class);menu.setAccessible(true);Library.Track cloud=song("1","Первый трек");menu.invoke(ctrl.get(),cloud);AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();d.getListView().performItemClick(null,2,2);AlertDialog confirmation=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();confirmation.getButton(AlertDialog.BUTTON_POSITIVE).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertNull(new OfflineStore(c).find(saved.uri));assertTrue(new OfflineStore(c).excluded("1"));assertTrue(cloud.liked);assertNotNull(new Library(c).find("sc:1"));ctrl.destroy();}
 @Test public void headerNoLongerContainsAppName()throws Exception{ActivityController<FakeMain> ctrl=screen("likes","");for(View v:all(ctrl.get().getWindow().getDecorView()))if(v instanceof TextView)assertNotEquals("SoundFlow",((TextView)v).getText().toString());ctrl.destroy();}
}
